Q=[
make(1,"A chart shows books borrowed: Monday 12, Tuesday 18, Wednesday 15. Which sentence is correct?",{"A":"Students borrowed the most books on Tuesday.","B":"Wednesday had more books than Tuesday.","C":"Monday and Tuesday had the same number.","D":"Students borrowed no books on Monday."},"A","The largest value is 18 on Tuesday, so Tuesday had the highest number.","Compare the three numerical labels and select the sentence matching the maximum.",["Read all three values: 12, 18, and 15.","Identify the largest value: 18.","Match 18 with Tuesday.","Reject statements that reverse or erase the data.","Choose A because it accurately states the chart maximum."],"easy"),
make(2,"A weather icon chart shows Monday sunny, Tuesday rainy, and Wednesday cloudy. What sentence matches the chart?",{"A":"It was rainy on Tuesday.","B":"It was sunny on Wednesday.","C":"It was cloudy on Monday.","D":"It rained on all three days."},"A","The Tuesday icon is rainy, so A directly converts the symbol into a sentence.","Map each icon to its labeled day before choosing the corresponding sentence.",["Read the day labels in order.","Match Tuesday with the rain icon.","Convert the icon into It was rainy.","Reject the weather symbols assigned to other days.","Select A because its day and condition match."],"easy"),
make(3,"A pie chart shows club choices: sports 40%, music 35%, art 25%. Which comparison is supported?",{"A":"Sports is more popular than art.","B":"Art is more popular than sports.","C":"Music has no members.","D":"All three clubs have the same share."},"A","Forty percent is greater than twenty-five percent, so sports has a larger share than art.","Compare the percentages directly and avoid treating the chart categories as equal without evidence.",["Locate sports at 40%.","Locate art at 25%.","Compare the two percentages.","Reject the reversed, zero, and equal-share claims.","Choose A because 40 is greater than 25."],"easy"),
make(4,"A map icon places the library north of the park and the café east of the library. Which sentence is correct?",{"A":"The café is east of the library.","B":"The park is east of the café.","C":"The library is south of the park.","D":"The café is inside the park."},"A","The diagram explicitly places the café east of the library; the other relations are not shown.","Read the directional arrow and preserve the reference point named after of.",["Identify the reference point: the library.","Read the direction: east.","Locate the café as the object in that relation.","Reject reversed or invented locations.","Choose A because it restates the diagram exactly."],"easy"),
make(5,"A process diagram reads: wash the cup → add tea → pour hot water → wait three minutes. What should happen after adding tea?",{"A":"Pour hot water.","B":"Wash the cup.","C":"Wait three minutes before adding tea.","D":"Drink before adding water."},"A","The arrow after add tea points to pour hot water, so A is the next step.","Follow the arrows one step at a time rather than choosing a step from the whole process.",["Locate add tea in the sequence.","Read the next box connected by the arrow.","Match it with pour hot water.","Reject earlier, reordered, and unsafe alternatives.","Choose A because it is the immediate next step."],"easy"),
make(6,"A line chart shows water use falling from 80 liters in April to 60 in May and 45 in June. Which sentence describes the trend?",{"A":"Water use decreased each month.","B":"Water use increased every month.","C":"Water use stayed at 80 liters.","D":"June used more water than April."},"A","The values move from 80 to 60 to 45, so water use decreases at each step.","Read the values in time order and compare each adjacent pair.",["Record April's value: 80.","Compare May's 60 with April.","Compare June's 45 with May.","Reject claims of increase, no change, or June exceeding April.","Select A because both month-to-month changes are downward."],"medium"),
make(7,"A table lists travel times: bus 35 minutes, bicycle 20 minutes, walking 50 minutes. Which sentence uses a superlative correctly?",{"A":"Walking is the slowest option.","B":"Bicycle is slower than walking.","C":"Bus is the fastest option.","D":"Walking takes less time than bicycle."},"A","Walking takes the longest time, so it is the slowest option among the three.","Identify the extreme value and choose a sentence whose comparison word matches it.",["List the times: 35, 20, and 50 minutes.","Find the greatest time: walking at 50.","Translate greatest travel time into slowest option.","Check the other comparisons for reversed values.","Choose A because it correctly names the slowest route."],"medium"),
make(8,"A classroom floor plan shows four desks in a row. The plant is beside Desk 1, and the trash bin is between Desk 3 and the door. Which sentence matches the plan?",{"A":"The plant is beside Desk 1.","B":"The trash bin is between Desk 1 and Desk 2.","C":"Desk 3 is inside the door.","D":"The plant is beside the trash bin."},"A","The plan explicitly states the plant is beside Desk 1; no other option matches the given positions.","Anchor each object to the exact landmark named in the diagram description.",["Locate the plant's reference: Desk 1.","Read the relation: beside.","Check whether another option changes the reference or invents a relation.","Reject the bin and door claims not stated.","Choose A because it matches the plan's labeled position."],"easy"),
make(9,"A survey asks how students travel: walk 10, bus 22, bicycle 8. Which conclusion is reasonable?",{"A":"The bus is the most common way in this survey.","B":"Everyone travels by bus.","C":"Bicycle is more common than bus.","D":"No student walks to school."},"A","Bus has the largest count, 22, so it is most common in this survey; A does not overstate the result.","Find the largest category and keep the conclusion limited to the surveyed students.",["Read each count: walk 10, bus 22, bicycle 8.","Identify the largest count: bus 22.","Form a most-common conclusion.","Reject everyone, reversed comparison, and zero claims.","Choose A because it is both supported and appropriately scoped."],"medium"),
make(10,"A bar chart shows a project score of 6 before revision and 9 after revision. Which sentence best summarizes the data?",{"A":"The score increased by three points after revision.","B":"The score fell by three points after revision.","C":"The score did not change.","D":"The first score was nine and the second was six."},"A","Subtracting 6 from 9 gives 3, and the later bar is higher, so the score increased by three points.","Read both bars, preserve their time order, and calculate the difference with the correct direction.",["Identify the earlier score: 6.","Identify the later score: 9.","Subtract 6 from 9 to find a difference of 3.","Check the direction: the later bar is higher.","Choose A because it states magnitude and direction correctly."],"hard"),
]
